 const levels=project.levels?.length?project.levels:defaultLevels;const cadLayers=Array.from(new Set(project.elements.map(e=>String(e.properties.cadLayer||'')).filter(Boolean))).sort();const visibleElements=project.elements.filter(e=>(activeLevel==='Todos'||e.level===activeLevel)&&(phaseFilter==='Todas'||String(e.properties.phase||'Novo')===phaseFilter)&&e.properties.hidden!==true&&!hiddenCadLayers.includes(String(e.properties.cadLayer||'')));const phaseCounts={novo:project.elements.filter(e=>String(e.properties.phase||'Novo')==='Novo').length,existente:project.elements.filter(e=>String(e.properties.phase||'Novo')==='Existente').length,demolir:project.elements.filter(e=>String(e.properties.phase||'Novo')==='Demolir').length};const overlayDrawing=drawings.find(d=>d.cadSegments?.length);
 async function importStrut(f?:File){if(!f)return;try{const p=JSON.parse(await f.text()) as RJPStudioStructurePackage;if(p.schema!=='RJP-STUDIO-STRUCTURE/1.0')throw new Error('Formato SmartStruct/RJP_3D não reconhecido.');const pr=projectFromStrut(p);save(pr);generateWorks(pr);setPage('model')}catch(e){alert(e instanceof Error?e.message:'Não foi possível importar.')}}
