 const validateBim=()=>{const issues:string[]=[];const ids=new Set<string>();project.elements.forEach(e=>{if(ids.has(e.id))issues.push(`ID duplicado: ${e.id}`);ids.add(e.id);if(!e.level)issues.push(`${e.name}: sem nível`);if(!e.material?.id)issues.push(`${e.name}: sem material`);if(e.size.x<=0||e.size.y<=0||e.size.z<=0)issues.push(`${e.name}: dimensão inválida`);if(e.type==='window'||e.type==='door'){if(!e.properties.hostWallId)issues.push(`${e.name}: vão sem parede hospedeira`)}});setBimIssues(issues);if(!issues.length)alert('Validação BIM concluída: sem problemas críticos.');};const exportProjectPackage=()=>{const pack={schema:'RJP-3D-STUDIO/3.7',version:'3.7.2',exportedAt:now(),project,works,measurements,siteEntries,rooms,sheets,drawings:drawings.map(({url,...d})=>d)};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(pack,null,2)],{type:'application/json'}));a.download=`${project.name.replace(/[^a-z0-9_-]+/gi,'_')||'RJP_3D'}_V37.rjp3d.json`;a.click();URL.revokeObjectURL(a.href)};const setElementLevel=(e:StudioElement,levelName:string)=>{const lv=levels.find(l=>l.name===levelName);updateEl(e.id,{level:levelName,position:{...e.position,z:(lv?.elevation||0)+e.size.z/2}})};
 const addWall=()=>{const L=Math.max(.2,n(prompt('Comprimento da parede (m)','4')||4)),T=Math.max(.05,n(prompt('Espessura (m)',String(cadThickness))||cadThickness)),H=Math.max(.2,n(prompt('Altura (m)',String(cadHeight))||cadHeight)),lv=levels.find(l=>l.name===(activeLevel==='Todos'?'Piso 0':activeLevel))||levels[0],mat=materials.find(m=>m.texture==='brick')||materials[0];const e:StudioElement={id:`WALL-${Date.now()}`,name:'Parede BIM',type:'wall',category:'Alvenarias',level:lv.name,position:{x:2+project.elements.length*.15,y:2,z:lv.elevation+H/2},rotation:{x:0,y:0,z:0},size:{x:L,y:T,z:H},material:mat,source:'RJP CAD',properties:{phase:'Novo',smartWall:true,joinMode:'auto',snap:snapMode}};save({...project,elements:[...project.elements,e]});setSelected(e.id);setPage('model')};
 const addOpening=(kind:'door'|'window')=>{const walls=project.elements.filter(e=>e.type==='wall');if(!walls.length)return alert('Crie ou importe primeiro uma parede.');const host=(sel?.type==='wall'?sel:walls[0]);const W=Math.max(.4,n(prompt('Largura do vão (m)',kind==='door'?'.90':'1.20')||(kind==='door'?'.90':'1.20'))),H=Math.max(.4,n(prompt('Altura do vão (m)',kind==='door'?'2.10':'1.20')||(kind==='door'?'2.10':'1.20'))),sill=kind==='door'?0:Math.max(0,n(prompt('Peitoril (m)','.90')||.9)),mat=materials.find(m=>kind==='window'?m.texture==='glass':m.texture==='wood')||materials[0];const e:StudioElement={id:`${kind.toUpperCase()}-${Date.now()}`,name:kind==='door'?'Porta hospedada':'Janela hospedada',type:kind,category:'Vãos',level:host.level,position:{x:host.position.x,y:host.position.y,z:(levels.find(l=>l.name===host.level)?.elevation||0)+sill+H/2},rotation:{...host.rotation},size:{x:W,y:Math.max(.06,host.size.y+.02),z:H},material:mat,source:'RJP CAD',properties:{phase:'Novo',hostWallId:host.id,hostCut:true,sillHeight:sill}};save({...project,elements:[...project.elements,e]});setSelected(e.id)};
 const detectRooms=()=>{const segs=overlayDrawing?.cadSegments||[];if(!segs.length)return alert('Importe/ative uma planta DWG ou DXF para analisar compartimentos.');const b=overlayDrawing?.cadBounds;if(!b)return;const area=Math.max(0,(b.maxX-b.minX)*(b.maxY-b.minY)*cadScale*cadScale);const walls=project.elements.filter(e=>e.type==='wall'&&(activeLevel==='Todos'||e.level===activeLevel));const estimated=Math.max(1,Math.round(Math.max(1,walls.length)/4));const per=area/estimated;const next:RoomZone[]=Array.from({length:estimated},(_,i)=>({id:`ROOM-${Date.now()}-${i}`,name:`Compartimento ${i+1}`,level:activeLevel==='Todos'?'Piso 0':activeLevel,area:+per.toFixed(2),perimeter:+(4*Math.sqrt(per)).toFixed(2),source:'CAD'}));setRooms(next);localStorage.setItem('rjp3d:rooms',JSON.stringify(next));setPage('rooms')};
 const addSheet=()=>{const title=prompt('Título da folha','Planta geral');if(!title)return;const sh:DrawingSheet={id:`SHEET-${Date.now()}`,number:`A-${String(sheets.length+1).padStart(2,'0')}`,title,size:'A1',scale:'1:100',view:'Planta',level:activeLevel==='Todos'?'Piso 0':activeLevel,revision:'P01'};const x=[...sheets,sh];setSheets(x);localStorage.setItem('rjp3d:sheets',JSON.stringify(x));setPage('sheets')};
 const refreshHostedOpenings=()=>{let linked=0;const els=project.elements.map(e=>{if(!['door','window'].includes(e.type))return e;let host=project.elements.find(w=>w.id===String(e.properties.hostWallId||'')&&w.type==='wall');if(!host){host=project.elements.filter(w=>w.type==='wall'&&w.level===e.level).sort((x,y)=>Math.hypot(x.position.x-e.position.x,x.position.y-e.position.y)-Math.hypot(y.position.x-e.position.x,y.position.y-e.position.y))[0]}if(!host)return e;linked++;return{...e,properties:{...e.properties,hostWallId:host.id,openingCut:true,openingWidth:e.size.x,openingHeight:e.size.z,openingSill:e.type==='window'?(e.properties?.sillHeight??.9):0}}});save({...project,elements:els});alert(`${linked} vãos ligados/atualizados. O viewport usa a relação hospedeira; o CSG destrutivo continua protegido para não corromper o modelo.`)}
