 const offsetSelected=()=>{const e=project.elements.find(x=>x.id===selected);if(!e||e.type!=='wall')return alert('Selecione uma parede.');const d=Number(prompt('Offset (m):','0.20')||0);if(!d)return;const L=e.size.x/2,ang=e.rotation.z,c=Math.cos(ang),s=Math.sin(ang),p1={x:e.position.x-L*c,y:e.position.y-L*s},p2={x:e.position.x+L*c,y:e.position.y+L*s},[a,b]=offsetSegment(p1,p2,d),mat=e.material;const nw=makeWall(a,b,e.level||'Piso 0',e.position.z-e.size.z/2,e.size.z,e.size.y,mat,'Offset');nw.name=e.name+' · Offset';save({...project,elements:[...project.elements,nw]});setSelected(nw.id)}
