 const mirrorSelected=()=>{const e=project.elements.find(x=>x.id===selected);if(!e)return;const x=Number(prompt('Eixo vertical X (m):','0')||0),p=mirrorPoint({x:e.position.x,y:e.position.y},{x,y:-1000},{x,y:1000}),n={...e,id:`MIRROR-${Date.now()}`,name:e.name+' · Espelho',position:{...e.position,x:p.x,y:p.y},rotation:{...e.rotation,z:Math.PI-e.rotation.z},properties:{...e.properties}};save({...project,elements:[...project.elements,n]});setSelected(n.id)}
 const trimSelected=()=>{const e=project.elements.find(x=>x.id===selected);if(!e||e.type!=='wall')return alert('Selecione a parede a aparar.');const target=project.elements.filter(x=>x.type==='wall'&&x.id!==e.id).sort((x,y)=>Math.hypot(x.position.x-e.position.x,x.position.y-e.position.y)-Math.hypot(y.position.x-e.position.x,y.position.y-e.position.y))[0];if(!target)return;const patch=trimWallToIntersection(e,target);if(!patch)return alert('As paredes são paralelas.');updateEl(e.id,patch)}
