 const startCadDraw=(tool:'Linha'|'Polilinha'|'Parede'|'Retângulo')=>{setCadTool(tool);setNavigationMode('select');setViewMode('top');setDrawStart(null);setRectStart(null);setCmdMessage(tool==='Linha'?'LINHA → 2 pontos = 1 parede BIM':tool==='Retângulo'?'RETÂNGULO → 2 cantos = 4 paredes BIM':'POLILINHA/PAREDE → clique sucessivamente; Enter/Esc termina')}
 const canvasPoint=(raw:{x:number;y:number})=>{if(!['Parede','Linha','Polilinha'].includes(cadTool))return;const p=nearestSnap(raw,project.elements,snapMode);if(!drawStart){setDrawStart(p);setCmdMessage(`${cadTool}: primeiro ponto ${p.x.toFixed(2)}, ${p.y.toFixed(2)} · indique o seguinte`);return}const lv=levels.find(l=>l.name===(activeLevel==='Todos'?'Piso 0':activeLevel))||levels[0],mat=materials.find(m=>m.texture==='brick')||materials[0];const wall=makeWall(drawStart,p,lv.name,lv.elevation,cadHeight,cadThickness,mat,snapMode);wall.name=cadTool==='Linha'?'Parede · Linha':'Parede BIM';save({...project,elements:[...project.elements,wall]});setSelected(wall.id);if(cadTool==='Linha'){setDrawStart(null);setCmdMessage(`LINHA concluída · parede ${wall.size.x.toFixed(2)} m`)}else{setDrawStart(p);setCmdMessage(`${cadTool}: parede ${wall.size.x.toFixed(2)} m · próximo ponto ou Enter para terminar`)}}
 const rectanglePoint=(raw:{x:number;y:number})=>{if(cadTool!=='Retângulo')return;const p=nearestSnap(raw,project.elements,snapMode);if(!rectStart){setRectStart(p);setCmdMessage(`RETÂNGULO: primeiro canto ${p.x.toFixed(2)}, ${p.y.toFixed(2)} · indique canto oposto`);return}const a=rectStart,b=p,pts=[a,{x:b.x,y:a.y},b,{x:a.x,y:b.y}],lv=levels.find(l=>l.name===(activeLevel==='Todos'?'Piso 0':activeLevel))||levels[0],mat=materials.find(m=>m.texture==='brick')||materials[0];const walls=pts.map((p0,i)=>{const p1=pts[(i+1)%4],w=makeWall(p0,p1,lv.name,lv.elevation,cadHeight,cadThickness,mat,snapMode);w.name='Parede · Retângulo';return w});save({...project,elements:[...project.elements,...walls]});setSelected(walls[0].id);setRectStart(null);setCmdMessage(`RETÂNGULO concluído · ${(Math.abs(b.x-a.x)).toFixed(2)} × ${(Math.abs(b.y-a.y)).toFixed(2)} m · 4 paredes BIM`)}
